impl Solution{pub fn count_range_sum(nums:Vec<i32>,lower:i32,upper:i32)->i32{fn f(a:&mut Vec<i64>,tmp:&mut Vec<i64>,l:usize,r:usize,lo:i64,hi:i64)->i64{if r-l<=1{return 0}let m=(l+r)/2;let mut c=f(a,tmp,l,m,lo,hi)+f(a,tmp,m,r,lo,hi);let(mut p,mut q)=(m,m);for i in l..m{while p<r&&a[p]-a[i]<lo{p+=1}while q<r&&a[q]-a[i]<=hi{q+=1}c+=(q-p)as i64;}let(mut i,mut j,mut k)=(l,m,l);while i<m||j<r{if j==r||(i<m&&a[i]<=a[j]){tmp[k]=a[i];i+=1}else{tmp[k]=a[j];j+=1}k+=1;}for i in l..r{a[i]=tmp[i]}c}let mut a=vec![0i64;nums.len()+1];for i in 0..nums.len(){a[i+1]=a[i]+nums[i]as i64}let mut tmp=a.clone();f(&mut a,&mut tmp,0,nums.len()+1,lower as i64,upper as i64)as i32}}
